<script setup lang="ts">
const { analyticsRange } = useUiState()
const rangeIds = ['30d', '90d', 'all'] as const
const weeks = Array.from({ length: 52 }, (_, i) => i)

const heatClass = (i: number, j: number) => {
  const n = (i * 17 + j * 31) % 11
  if (n <= 1) return 'bg-surface-container'
  if (n <= 3) return 'bg-primary/20'
  if (n <= 5) return 'bg-primary/40'
  if (n <= 7) return 'bg-primary/60'
  if (n <= 9) return 'bg-primary/80'
  return 'bg-primary'
}
</script>

<template>
  <main class="mx-auto min-h-screen max-w-6xl space-y-12 p-6 md:p-12">
    <header class="flex flex-col gap-6 md:flex-row md:items-end md:justify-between">
      <PageHeader title="Living" accent="Work" />
      <div class="flex rounded-lg bg-surface-container-low p-1">
        <button
          v-for="id in rangeIds"
          :key="id"
          class="rounded-md px-6 py-2 font-mono text-[10px] font-bold"
          :class="analyticsRange === id ? 'bg-surface-container-high text-on-surface' : 'text-on-surface/40'"
          @click="analyticsRange = id"
        >
          {{ id }}
        </button>
      </div>
    </header>

    <section class="rounded-xl border-l-4 border-primary bg-surface-container-low p-8">
      <h2 class="mb-6 font-headline text-2xl font-bold">Contribution Density</h2>
      <div class="grid max-w-full gap-1 overflow-x-auto pb-4" style="grid-template-columns: repeat(52, minmax(12px, 1fr));">
        <div v-for="w in weeks" :key="w" class="flex flex-col gap-1">
          <div v-for="d in 7" :key="d" :class="['h-3 w-3 rounded-sm', heatClass(w, d)]" />
        </div>
      </div>
    </section>
  </main>
</template>
